import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Fingerprint, Loader2, Zap, Triangle, Target, Shield } from 'lucide-react';

const SignIn = ({ onLogin }) => {
  const [loading, setLoading] = useState(false);
  const [hovered, setHovered] = useState(false);

  const triggerAuth = (e) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      onLogin();
    }, 2500);
  };

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center p-6 overflow-hidden font-sans selection:bg-[#FF5B03] selection:text-white">

      {/* BACKGROUND GRID - Gives it that technical 'Neo' depth */}
      <div className="absolute inset-0 opacity-[0.03] pointer-events-none" 
           style={{ backgroundImage: `radial-gradient(#47510B 1px, transparent 1px)`, size: '40px 40px', backgroundSize: '30px 30px' }} />

      {/* FLOATING DECORATIVE ELEMENTS */}
      <div className="absolute top-10 left-10 text-[#47510B]/20 font-black text-xs tracking-[1em] uppercase vertical-text">
        System.Auth.09
      </div>

      <motion.div 
        initial={{ opacity: 0, scale: 1.1 }}
        animate={{ opacity: 1, scale: 1 }}
        className="w-full max-w-5xl grid grid-cols-1 lg:grid-cols-12 gap-0 relative z-10 border-[3px] border-[#47510B] bg-white shadow-[24px_24px_0px_0px_#47510B]"
      >
        {/* LEFT SIDE: THE ENERGY SIDE */}
        <div className="lg:col-span-7 bg-[#47510B] p-12 flex flex-col justify-between relative overflow-hidden">
          <motion.div 
            animate={{ rotate: 360 }}
            transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
            className="absolute -top-20 -left-20 w-96 h-96 border border-[#CAD23C]/10 rounded-full"
          />

          <div className="relative z-10">
            <div className="flex items-center gap-4 mb-12">
              <div className="w-12 h-12 bg-[#CAD23C] flex items-center justify-center">
                <Target size={24} className="text-[#47510B]" />
              </div>
              <span className="text-[#CAD23C] font-black tracking-widest text-[10px] uppercase">Terminal_Active</span>
            </div>

            <h1 className="text-[100px] leading-[0.8] font-[1000] italic text-white uppercase tracking-tighter">
              WORKER <br/>
              <span className="text-[#CAD23C]">FORCE.</span>
            </h1>
          </div>

          <div className="relative z-10 mt-20">
            <p className="text-[#CAD23C]/50 font-bold text-sm max-w-xs leading-tight uppercase italic">
              Level up your efficiency. <br/> Access the industrial vanguard network.
            </p>
          </div>
        </div>

        {/* RIGHT SIDE: THE ACTION SIDE */}
        <div className="lg:col-span-5 bg-white p-12 flex flex-col justify-center relative">

          <form onSubmit={triggerAuth} className="space-y-8">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-widest ml-1">Credential_Entry</label>
              <div className="relative border-b-[3px] border-[#47510B]/10 focus-within:border-[#FF5B03] transition-colors">
                <input 
                  required
                  type="text" 
                  placeholder="ID_NUMBER"
                  className="w-full py-4 bg-transparent font-black text-2xl text-[#47510B] outline-none placeholder-[#47510B]/10 uppercase italic"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-widest ml-1">Security_Key</label>
              <div className="relative border-b-[3px] border-[#47510B]/10 focus-within:border-[#FF5B03] transition-colors">
                <input 
                  required
                  type="password" 
                  placeholder="••••••••"
                  className="w-full py-4 bg-transparent font-black text-2xl text-[#47510B] outline-none placeholder-[#47510B]/10"
                />
              </div>
            </div>

            <motion.button 
              onHoverStart={() => setHovered(true)}
              onHoverEnd={() => setHovered(false)}
              className="w-full bg-[#FF5B03] text-white p-6 flex items-center justify-between group relative overflow-hidden"
              style={{ boxShadow: hovered ? '8px 8px 0px 0px #47510B' : '0px 0px 0px 0px #47510B' }}
              transition={{ duration: 0.2 }}
            >
              <span className="font-black text-2xl uppercase italic tracking-tighter relative z-10">
                {loading ? 'Verifying...' : 'Start Session'}
              </span>

              <AnimatePresence mode="wait">
                {loading ? (
                  <Loader2 key="l" className="animate-spin text-white" size={32} />
                ) : (
                  <div className="flex gap-2 relative z-10">
                    <Fingerprint size={32} />
                  </div>
                )}
              </AnimatePresence>

              {/* UNCONVENTIONAL HOVER SLIDE */}
              <motion.div 
                className="absolute inset-0 bg-[#47510B]"
                initial={{ x: '-101%' }}
                animate={{ x: hovered ? '0%' : '-101%' }}
                transition={{ duration: 0.3, ease: "circOut" }}
              />
            </motion.button>
          </form>

          {/* BOTTOM DECORATION */}
          <div className="absolute bottom-8 right-8 flex gap-4 opacity-10">
             <Shield size={40} className="text-[#47510B]" />
             <Zap size={40} className="text-[#47510B]" />
             <Triangle size={40} className="text-[#47510B]" strokeWidth={3} />
          </div>
        </div>
      </motion.div>

      {/* SCREEN SCANLINE EFFECT */}
      <div className="absolute inset-0 pointer-events-none bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.05)_50%),linear-gradient(90deg,rgba(255,0,0,0.02),rgba(0,255,0,0.01),rgba(0,0,255,0.02))] z-[100] bg-[length:100%_2px,3px_100%]" />
    </div>
  );
};

export default SignIn;
